INSERT INTO survey_question (question_id, prompt_minor, prompt_adult) VALUES
  ('q_portion', 'Was your food too little, just right, or too much?', 'How would you rate the portion size?'),
  ('q_service', 'Were the volunteers nice to you today?', 'How would you rate the service of the volunteers?'),
  ('q_taste', 'Did the food taste good?', 'How would you rate the taste of the food?'),
  ('q_satisfaction', 'How happy are you with today''s meal?', 'How satisfied are you with today''s meal overall?');
INSERT INTO status_definition (status_key, description, criteria) VALUES
  ('baseline', 'Within expected range for age and sex', 'MOCK RULE (BMI + WHtR + MUAC + Edema): Assigned when no edema is present, MUAC is within normal age-bracketed thresholds, child |BMI-for-age z| < 1.5 (or adult BMI 18.5-27.4), and WHtR <= 0.56.'),
  ('monitor', 'Mild-to-moderate deviation or elevated WHtR — watch trend across Timelines', 'MOCK RULE (BMI + WHtR + MUAC + Edema): Assigned when moderate wasting by MUAC (U5: 11.5-12.4cm, 5-9y: 13.5-14.4cm, 10-17y: 16.0-18.4cm, Adult: 21.0-22.9cm), child 1.5 <= |BMI-for-age z| < 2.5, adult BMI 16.0-18.4 or 27.5-34.9, or WHtR > 0.56.'),
  ('monitor_closely', 'Severe deviation or clinical priority (edema / severe MUAC) — prioritize follow-up', 'MOCK RULE (BMI + WHtR + MUAC + Edema): Highest severity override. Assigned when bilateral pitting edema is present, severe wasting by MUAC (U5: <11.5cm, 5-9y: <13.5cm, 10-17y: <16.0cm, Adult: <21.0cm), child |BMI-for-age z| >= 2.5, or adult BMI < 16.0 or >= 35.0.'),
  ('unavailable', 'Incomplete measurement data — status cannot be computed', 'Assigned when a beneficiary was present and partially measured in the Timeline (e.g., weight without height, or height without weight/waist) and has no MUAC or edema check, preventing BMI/WHtR calculation.');
INSERT INTO status_reason_definition (reason_key, description) VALUES
  ('normal', 'Within healthy anthropometric and clinical thresholds'),
  ('edema', 'Bilateral pitting edema present (SAM clinical priority)'),
  ('muac', 'Acute wasting indicated by Mid-Upper Arm Circumference (MUAC)'),
  ('bmi', 'BMI or BMI-for-age z-score outside healthy threshold'),
  ('whtr', 'Elevated central adiposity indicated by Waist-to-Height Ratio (WHtR > 0.56)'),
  ('incomplete_data', 'Incomplete anthropometric measurement (missing paired height or weight)');
