INSERT INTO session_note (note_id, session_id, category, note) VALUES
  ('36c4c32e-e36a-5fff-b72a-b1b24fc1ff1d', '7d5f4dfe-7058-5989-8d56-60f103798389', 'event', 'Program kickoff; the barangay captain gave a short opening message.'),
  ('df81edce-f7b4-5ced-9202-33a50f1af0d4', '34ebeea1-200d-54a4-8210-01467903219e', 'attendance', 'Heavy rain in the morning; several families arrived late.'),
  ('489ac533-7ad8-5443-94fa-4fdddd1a7dcb', '3f6f2a62-e345-5933-82f4-24cd49658c79', 'leftovers', 'About 2kg of rice left over; reduce next week''s rice portion.'),
  ('0cb296e0-dd3c-5630-b3d8-c3b8a6aa4879', 'af8d7456-aca1-5f40-ba11-ceb415f535c4', 'incident', 'Three children reported loose bowel movements after the session; referred to the barangay health worker.'),
  ('acd2b221-51d9-5ab6-9bdc-0ac419850edf', 'd0859673-755c-5e1c-a81b-b77c79591923', 'event', 'Barangay health worker gave a short handwashing demo before the meal.'),
  ('3e0cde40-0879-556b-a0c2-d35d6f8c50c1', '0dea938f-fdf0-505c-870c-6f947af449c8', 'leftovers', 'Vegetable soup ran out early while rice was left over again.'),
  ('6aa79029-cd58-56a4-8320-6f7bc97f45ca', 'b5fff2e1-1fa0-5aff-956c-903fc5aef117', 'event', 'Last session; participation certificates handed out.'),
  ('ea8bb4f7-1cfa-579e-90d4-c8daf386727c', 'b5fff2e1-1fa0-5aff-956c-903fc5aef117', 'attendance', 'Several beneficiaries left right after eating.'),
  ('16387c49-e35e-54e4-8987-b7b6cc7d0003', 'f1bdf71c-8ab5-5eaf-8712-a64ac56f842c', 'event', 'First session; volunteers set up long tables outside the hall.'),
  ('72f9bc05-6ce7-5f2e-9364-88ae29cea069', '6b2f1eae-0f90-5203-88fa-1c3a0a08c323', 'leftovers', 'Extra pancit left over; shared with neighbors.'),
  ('40c27d60-f772-5d59-aac2-2c9f1a977786', '62a74d6f-310f-5db5-a07d-cefee3dc3507', 'incident', '20-minute power outage; weighing continued by daylight.'),
  ('e62f5afc-08c0-5cb6-b78f-b4fc6d3ec9f6', '06e75f00-90a9-5b7b-b2a4-5c99464a446c', 'attendance', 'Entry in progress; weighing scale battery replaced halfway.');
