INSERT INTO ai_interpretation (interpretation_id, scope, session_id, timeline_id, category, comments, created_at) VALUES
  ('5dea82f2-0202-5a01-aacc-7e8d89cb0294', 'timeline', NULL, 'f1b16502-2064-5714-b587-d99f50e3343f', 'nutrition_trend', 'First Timeline (June 1 to June 15): 47 of 60 beneficiaries were measured (78%). Mean BMI is 14.8. 32 are at baseline, 11 need monitoring and 4 need closer monitoring. With no earlier Timeline, there is no trend yet.', '2026-06-15 14:07:52'),
  ('815eea49-9cff-5724-b556-80e491b3e6db', 'timeline', NULL, '3019cc72-40da-544e-a56a-7b5bd7f6649e', 'nutrition_trend', 'Timeline 2 (June 15 to June 29): mean BMI moved from 14.8 to 15.1. 47 of 60 beneficiaries were measured (78%). 4 need closer monitoring (previously 4); 19 of 36 comparable beneficiaries moved closer to a healthy range.', '2026-06-29 15:41:33'),
  ('8ad1be9e-bcfb-520c-8b61-8ef416ff986b', 'timeline', NULL, '29527fc5-1361-5a69-b0cf-80304b231f92', 'nutrition_trend', 'Timeline 3 (June 29 to July 13): mean BMI moved from 15.1 to 15.2. 44 of 60 beneficiaries were measured (73%). 1 needs closer monitoring (previously 4); 21 of 38 comparable beneficiaries moved closer to a healthy range.', '2026-07-13 17:24:36'),
  ('d0a8e80b-e1c6-51f9-b268-9e444f342ed2', 'timeline', NULL, '98b85d64-f594-570e-82d5-b703b9e7bd4b', 'nutrition_trend', 'Timeline 4 (July 13 to July 20): mean BMI moved from 15.2 to 15.2. 35 of 60 beneficiaries were measured (58%). 2 need closer monitoring (previously 1); 15 of 27 comparable beneficiaries moved closer to a healthy range.', '2026-07-20 17:23:53'),
  ('3d7acc3e-0d38-5654-9233-f2f23132db7d', 'timeline', NULL, 'fdd7a9f8-08fa-559a-b889-78f59dfce82f', 'nutrition_trend', 'First Timeline (September 22 to October 6): 40 of 45 beneficiaries were measured (89%). Mean BMI is 18.1. 25 are at baseline, 8 need monitoring and 7 need closer monitoring. With no earlier Timeline, there is no trend yet.', '2026-10-06 16:20:04'),
  ('2336f1c8-56c8-5d09-a3af-3fe8010ec8ce', 'session', '3f6f2a62-e345-5933-82f4-24cd49658c79', NULL, 'attendance_trend', 'Attendance dipped from 100% to 87% compared with session 1. Leftover rice was reported again.', '2026-06-15 14:07:52'),
  ('50a57d6f-51bc-5564-ac86-36d88749d9f1', 'session', 'af8d7456-aca1-5f40-ba11-ceb415f535c4', NULL, 'attendance_trend', 'Attendance dipped from 90% to 87% compared with session 4. Some children reported stomach upset after the meal; follow up with the health worker.', '2026-06-29 15:41:33'),
  ('4ea8087e-1fea-59e3-8761-bc6d114fae0c', 'session', '34ebeea1-200d-54a4-8210-01467903219e', NULL, 'privacy_concern', 'All 50 registered beneficiaries are minors. Make sure guardian consent is recorded before any child''s name is stored.', '2026-06-08 17:47:30'),
